// ═══ CREATE synchronizedMap ═══
Map<String, BigDecimal> balances = Collections.synchronizedMap(new HashMap<>());
balances.put("SAV2001", new BigDecimal("75000"));  // synchronized!
balances.get("SAV2001");                            // synchronized!

// ═══ ITERATION: MUST synchronize externally! ═══
// ❌ WRONG — ConcurrentModificationException possible!
for (Map.Entry<String, BigDecimal> entry : balances.entrySet()) {
    // Another thread calls balances.put() → CME!
}

// ✅ CORRECT — synchronize on the map!
synchronized (balances) {
    for (Map.Entry<String, BigDecimal> entry : balances.entrySet()) {
        // Safe — no other thread can modify during iteration
        process(entry.getKey(), entry.getValue());
    }
}
// BUT: entire map is LOCKED during iteration — no reads, no writes!
// For 100K entries: map locked for the entire scan duration. SLOW!

// ═══ WHY ConcurrentHashMap IS BETTER ═══
ConcurrentHashMap<String, BigDecimal> chm = new ConcurrentHashMap<>();
// Iteration: NO external sync needed!
for (Map.Entry<String, BigDecimal> entry : chm.entrySet()) {
    // Weakly consistent: sees elements as of some point during iteration
    // NEVER throws CME! Other threads can read/write simultaneously!
}

// ═══ COMPOUND OPERATIONS: synchronizedMap FAILS ═══
// check-then-act is NOT atomic in synchronizedMap:
if (!balances.containsKey("SAV2001")) {    // step 1: check
    balances.put("SAV2001", BigDecimal.ZERO); // step 2: act
    // Another thread can put() between step 1 and 2! RACE CONDITION!
}
// Must manually synchronize:
synchronized (balances) {
    if (!balances.containsKey("SAV2001")) {
        balances.put("SAV2001", BigDecimal.ZERO);
    }
}

// ConcurrentHashMap: atomic!
chm.computeIfAbsent("SAV2001", k -> BigDecimal.ZERO);  // ONE atomic operation!
